import React, { useEffect } from "react";
import * as Curve from "@visx/curve";
import * as Shape from "@visx/shape";
import _ from "lodash";
import { Motion, spring } from "react-motion";

import "../assets/css/circles.css";

function HomeAnimation(props) {
  // In pixels
  let period = 100;
  let amplitude = 40;

  let width = 30 * Math.PI;
  let height = 100;

  let data = [];

  // Once for each pixel, maybe reducible?
  _.times(width, (step) => {
    let transformedStep = step + props.time;
    let result = amplitude * Math.sin((Math.PI / period) * transformedStep);
    data.push([step, result + 50]);
  });

  let calculateData = (input) => {
    let newData = [];

    _.times(width, (step) => {
      let transformedStep = step + input;
      let result = amplitude * Math.sin((Math.PI / period) * transformedStep);
      newData.push([step, result + 50]);
    });

    return newData;
  };

  return (
    <Motion defaultStyle={{ inputStep: 0 }} style={{ inputStep: spring(100) }}>
      {(interpolatedStyle) => (
        <svg width={width} height={height}>
          <Shape.LinePath
            curve={Curve.curveCatmullRom}
            data={calculateData(interpolatedStyle.x)}
            stroke="black"
            strokeWidth={3}
          />
        </svg>
      )}
    </Motion>
  );
}

export default HomeAnimation;
